/**
 * Convert Excel date (days since Dec 30, 1899) to JavaScript Date
 */
function excelDateToJSDate(excelDate) {
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const msPerDay = 24 * 60 * 60 * 1000;
    return new Date(excelEpoch.getTime() + excelDate * msPerDay);
}

/**
 * Parse LST Note for early in (E) and late out (L) adjustments
 */
function parseLSTNote(lstNote) {
    if (!lstNote || typeof lstNote !== 'string') {
        return { earlyInHours: 0, lateOutHours: 0 };
    }

    const cleanNote = lstNote.trim().toUpperCase();
    let earlyInHours = 0;
    let lateOutHours = 0;

    // Match E pattern (Early in): E1, E0.5, E2.5, etc.
    const earlyMatch = cleanNote.match(/E(\d+(?:\.\d+)?)/);
    if (earlyMatch) {
        earlyInHours = parseFloat(earlyMatch[1]);
    }

    // Match L pattern (Late out): L1, L0.5, L1.5, etc.
    const lateMatch = cleanNote.match(/L(\d+(?:\.\d+)?)/);
    if (lateMatch) {
        lateOutHours = parseFloat(lateMatch[1]);
    }

    return { earlyInHours, lateOutHours };
}

/**
 * Create a time range from start/end hour and minute
 * @param {Date} baseDate - Base date to use for creating the time range
 * @param {number} startHour - Start hour (0-23)
 * @param {number} startMinute - Start minute (0-59)
 * @param {number} endHour - End hour (0-23)
 * @param {number} endMinute - End minute (0-59)
 * @returns {Object} Object with startTime and endTime Date objects
 */
function createTimeRange(baseDate, startHour, startMinute, endHour, endMinute) {
    // Create startTime using UTC to avoid timezone issues
    const startTime = new Date(Date.UTC(
        baseDate.getUTCFullYear(),
        baseDate.getUTCMonth(),
        baseDate.getUTCDate(),
        startHour,
        startMinute,
        0,
        0
    ));

    // Create endTime
    const endTime = new Date(Date.UTC(
        baseDate.getUTCFullYear(),
        baseDate.getUTCMonth(),
        baseDate.getUTCDate(),
        endHour,
        endMinute,
        0,
        0
    ));

    // If end time is before or equal to start time, add 1 day to endTime (midnight crossing)
    if (endTime <= startTime) {
        endTime.setUTCDate(endTime.getUTCDate() + 1);
    }

    return { startTime, endTime };
}

/**
 * Parse MYT time format and create Date objects for start and end times
 */
function parseMYTTime(mytString, shiftDate, lstNote) {
    if (!mytString || typeof mytString !== 'string') {
        throw new Error(`Invalid MYT format: ${mytString}`);
    }

    const cleanString = mytString.trim();
    const isCrossingShift = cleanString.toUpperCase().includes('(REAL)');
    const timeString = cleanString.replace(/\(REAL\)/i, '').trim();

    const timeMatch = timeString.match(/^(\d{1,2})(?::(\d{2}))?\s*>\s*(\d{1,2})(?::(\d{2}))?$/);

    if (!timeMatch) {
        throw new Error(`Invalid MYT time format: ${mytString}`);
    }

    const startHour = parseInt(timeMatch[1], 10);
    const startMinute = parseInt(timeMatch[2] || '0', 10);
    const endHour = parseInt(timeMatch[3], 10);
    const endMinute = parseInt(timeMatch[4] || '0', 10);

    // Use the extracted createTimeRange function
    const { startTime, endTime } = createTimeRange(shiftDate, startHour, startMinute, endHour, endMinute);

    // Apply LST Note adjustments
    // E (Early in) = both start and end earlier (subtract hours from both)
    // L (Late out) = both start and end later (add hours to both)
    const { earlyInHours, lateOutHours } = parseLSTNote(lstNote);

    if (earlyInHours > 0) {
        // Convert hours to milliseconds for accurate decimal handling
        const msToSubtract = earlyInHours * 60 * 60 * 1000;
        startTime.setTime(startTime.getTime() - msToSubtract);
        endTime.setTime(endTime.getTime() - msToSubtract);
    }

    if (lateOutHours > 0) {
        // Convert hours to milliseconds for accurate decimal handling
        const msToAdd = lateOutHours * 60 * 60 * 1000;
        startTime.setTime(startTime.getTime() + msToAdd);
        endTime.setTime(endTime.getTime() + msToAdd);
    }

    return {
        startTime,
        endTime,
        isCrossingShift
    };
}

/**
 * Parse BUSY column format and create assignedJobs array
 * Format: "start > end, start > end, ..."
 * @param {string} busyString - BUSY times from Excel
 * @param {Date} shiftStartTime - Shift start time
 * @param {Date} shiftEndTime - Shift end time
 */
function parseBusyColumn(busyString, shiftStartTime, shiftEndTime) {
    const assignedJobs = [];

    if (!busyString || typeof busyString !== 'string' || busyString.trim() === '') {
        return assignedJobs;
    }

    // Get the shift start hour to determine which date to use for BUSY times
    const shiftStartHour = shiftStartTime.getUTCHours();

    // Split by comma to get individual time ranges
    const timeRanges = busyString.split(',');

    for (const range of timeRanges) {
        const trimmedRange = range.trim();
        if (!trimmedRange) continue;

        // Match pattern: "start > end" or "start>end"
        const rangeMatch = trimmedRange.match(/^(\d{1,2})(?::(\d{2}))?\s*>\s*(\d{1,2})(?::(\d{2}))?$/);

        if (rangeMatch) {
            const startHour = parseInt(rangeMatch[1], 10);
            const startMinute = parseInt(rangeMatch[2] || '0', 10);
            const endHour = parseInt(rangeMatch[3], 10);
            const endMinute = parseInt(rangeMatch[4] || '0', 10);

            // Determine which date to use based on the BUSY start hour
            // If BUSY hour >= shift start hour, it's on the start date
            // If BUSY hour < shift start hour, it's on the end date (next day portion)
            const baseDate = startHour >= shiftStartHour ? shiftStartTime : shiftEndTime;

            // Use the extracted createTimeRange function
            const { startTime, endTime } = createTimeRange(baseDate, startHour, startMinute, endHour, endMinute);

            assignedJobs.push({
                type: "IC",
                start: startTime.toISOString(),
                end: endTime.toISOString()
            });
        }
    }

    return assignedJobs;
}

// Transform timeline data
const result = [];

for (const item of $input.all()) {
    const shiftDate = excelDateToJSDate(item.json.Date);
    const { startTime, endTime, isCrossingShift } = parseMYTTime(item.json.MYT, shiftDate, item.json['LST Note']);

    // Parse BUSY column to get assignedJobs
    // Pass both start and end times to handle crossing shifts correctly
    const assignedJobs = parseBusyColumn(item.json.Busy, startTime, endTime);

    result.push({
        json: {
            id: item.json.row_number,
            rowNumber: item.json.row_number,
            shiftDate: shiftDate,
            startTime,
            endTime,
            traderName: item.json.Trader,
            isCrossingShift,
            assignedJobs,
            nodeType: 'workingShift'
        }
    });
}

return result;

// Add nodeType to each working shift item
const items = $input.all();

return items.map(item => ({
  json: {
    ...item.json,
    nodeType: 'workingShift'
  },
  pairedItem: item.pairedItem
}));

/**
 * Create an assigned job object from a match
 */
function createAssignedJob(traderMatch) {
  return {
    type: traderMatch.betType,
    start: traderMatch.matchDate,
    end: traderMatch.endDate
  };
}

/**
 * Parse existing assignedJobs from shift data
 */
function parseAssignedJobs(shift) {
  if (!shift.assignedJobs) {
    return [];
  }

  if (typeof shift.assignedJobs === 'string') {
    try {
      return JSON.parse(shift.assignedJobs);
    } catch (e) {
      return [];
    }
  }

  if (Array.isArray(shift.assignedJobs)) {
    return [...shift.assignedJobs];
  }

  return [];
}

/**
 * Check if shift is a crossing shift for previous day
 */
function isPreviousDayCrossingShift(shift, previousDate) {
  if (!shift.isCrossingShift || !previousDate) {
    return false;
  }

  const shiftDate = new Date(shift.shiftDate);
  shiftDate.setUTCHours(0, 0, 0, 0);

  return shiftDate.getTime() === previousDate.getTime();
}

/**
 * Get previous date from matches
 */
function getPreviousDate(previousMatches) {
  if (previousMatches.length === 0) {
    return null;
  }

  const firstMatch = previousMatches[0].json;
  if (!firstMatch.matchDate) {
    return null;
  }

  const matchDate = new Date(firstMatch.matchDate);
  const previousDate = new Date(matchDate);
  previousDate.setUTCHours(0, 0, 0, 0);

  return previousDate;
}

/**
 * Find all matches for a trader
 */
function findTraderMatches(previousMatches, traderName) {
  return previousMatches.filter(matchItem => {
    const match = matchItem.json;
    return match.hdpTrader === traderName || match.ouTrader === traderName;
  });
}

/**
 * Enrich shift with assigned jobs from previous day matches
 */
function enrichShiftWithPreviousJobs(shift, previousMatches, previousDate) {
  let assignedJobs = parseAssignedJobs(shift);

  if (isPreviousDayCrossingShift(shift, previousDate)) {
    const traderMatchItems = findTraderMatches(previousMatches, shift.traderName);

    // Add all matched trader's jobs
    for (const traderMatchItem of traderMatchItems) {
      const job = createAssignedJob(traderMatchItem.json);
      assignedJobs.push(job);
    }
  }

  return assignedJobs;
}

// Main execution
const allItems = $input.all();

// Filter items by nodeType
const workingShifts = allItems.filter(item => item.json.nodeType === 'workingShift');
const previousMatches = allItems
  .filter(item => item.json.nodeType === 'mismatch')
  .sort((a, b) => {
    const dateA = new Date(a.json.matchDate);
    const dateB = new Date(b.json.matchDate);
    return dateA - dateB; // ascending order
  });

if (workingShifts.length === 0) {
  return [];
}

// Get previous date from first match
const previousDate = getPreviousDate(previousMatches);

// Enrich each working shift
const enrichedShifts = workingShifts.map(item => {
  const shift = item.json;
  const assignedJobs = enrichShiftWithPreviousJobs(shift, previousMatches, previousDate);

  return {
    json: {
      ...shift,
      assignedJobs: assignedJobs,
      nodeType: 'workingShift'
    },
    pairedItem: item.pairedItem
  };
});

return enrichedShifts;

/**
* Map staff level values to normalized format
*/
function mapStaffLevel(level) {
    if (!level) return null;

    const levelMap = {
        'elite': 'elite',
        'member': 'member',
        '(1st)': 'first',
        '(2nd)': 'second',
        '(3rd)': 'third',
        '(4th)': 'fourth',
        'op(1st)': 'op_first',
        'op(2nd)': 'op_second'
    };

    const lowerLevel = level.toLowerCase();
    return levelMap[lowerLevel] || level;
}

/**
 * Parse M1 and M2 capacity from bettype string
 * Default capacity is 1 if not specified
 * Examples:
 * - "HDP/M1*2" → { m1Capacity: 2, m2Capacity: 1 }
 * - "OU/M2*3" → { m1Capacity: 1, m2Capacity: 3 }
 * - "2/M1*2/M2*1" → { m1Capacity: 2, m2Capacity: 1 }
 * - "HDP/OU" → { m1Capacity: 1, m2Capacity: 1 } (default)
 */
function parseCapacity(bettype) {
    if (!bettype || typeof bettype !== 'string') {
        return { m1Capacity: 1, m2Capacity: 2 };
    }

    // Default capacity is 1
    let m1Capacity = 1;
    let m2Capacity = 1;

    // Match M1*<number>
    const m1Match = bettype.match(/M1\*(\d+)/i);
    if (m1Match) {
        m1Capacity = parseInt(m1Match[1], 10);
    }

    // Match M2*<number>
    const m2Match = bettype.match(/M2\*(\d+)/i);
    if (m2Match) {
        m2Capacity = parseInt(m2Match[1], 10);
    }

    return { m1Capacity, m2Capacity };
}

/**
 * Parse ignore league string into array
 * Examples:
 * - "league 1, league 2" → ["league 1", "league 2"]
 * - "EPL, LaLiga, SerieA" → ["EPL", "LaLiga", "SerieA"]
 * - "" or null → []
 */
function parseIgnoreLeague(ignoreLeagueStr) {
    if (!ignoreLeagueStr || typeof ignoreLeagueStr !== 'string') {
        return [];
    }

    // Split by comma and trim whitespace
    return ignoreLeagueStr
        .split(',')
        .map(league => league.trim())
        .filter(league => league.length > 0);
}

/**
 * Check if trader can be assigned to EXPT matches
 * Default is true, unless bettype contains "[No Expt]" (case-insensitive)
 * Examples:
 * - "HDP/M1*2" → true
 * - "2/M1*2[No Expt]" → false
 * - "OU/M2*3 [no expt]" → false
 * - "" or null → true
 */
function parseIsEXPTAssignable(bettype) {
    if (!bettype || typeof bettype !== 'string') {
        return true;
    }

    // Check if bettype contains "[No Expt]" (case-insensitive)
    return !bettype.match(/\[no\s*expt\]/i);
}

const result = [];

for (const item of $input.all()) {
    // Extract data from input
    const traderName = item.json.NAME;
    const traderLevel = item.json.LEVEL;
    const bettype = item.json['MAIN BET TYPE'];
    const group = item.json.GROUP;
    const ignoreLeague = item.json['Ignore League'];
    const rowNumber = item.json.row_number;

    // Initialize level objects
    let managementLevel = null;
    let staffLevel = null;
    let isManager = false;

    // Check if trader has PIC (People In Charge) - management level
    if (traderLevel && traderLevel.includes('[PIC]')) {
        isManager = true;
        managementLevel = '[PIC]';

        // Extract staff level from the remaining part
        const levelParts = traderLevel.split('/');

        if (levelParts.length > 1) {
            // Has both management and staff level (e.g., "[PIC]/Elite", "[PIC]/(1st)")
            staffLevel = levelParts[1];
        } else {
            // Only management level (e.g., "[PIC]")
            staffLevel = null;
        }
    } else {
        // No management level, only staff level
        managementLevel = null;
        staffLevel = traderLevel;
    }

    // Parse M1 and M2 capacity from bettype
    const { m1Capacity, m2Capacity } = parseCapacity(bettype);

    // Parse ignore league into array
    const ignoreLeagueArray = parseIgnoreLeague(ignoreLeague);

    // Parse EXPT assignability from bettype
    const isEXPTAssignable = parseIsEXPTAssignable(bettype);

    // Add to result array in n8n format
    result.push({
        json: {
            id: rowNumber,
            group: group,
            traderName,
            originalLevel: traderLevel,
            managementLevel: managementLevel,
            staffLevel: mapStaffLevel(staffLevel),
            isManager: isManager,
            bettype,
            ignoreLeague: ignoreLeagueArray,
            m1Capacity: m1Capacity,
            m2Capacity: m2Capacity,
            isEXPTAssignable: isEXPTAssignable,
            nodeType: 'trader'
        }
    });
}

return result;

// Filter items from 10:00 AM to 12:00 PM (not including 12:00 PM)
function parseTime(timeString) {
  const cleanTime = timeString.trim().replace(/\s+/g, ' ');
  const timeMatch = cleanTime.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);

  if (!timeMatch) return null;

  let hours = parseInt(timeMatch[1], 10);
  const minutes = parseInt(timeMatch[2], 10);
  const period = timeMatch[3].toUpperCase();

  // Convert to 24-hour format for comparison
  if (period === 'PM' && hours !== 12) {
    hours += 12;
  } else if (period === 'AM' && hours === 12) {
    hours = 0;
  }

  return hours * 60 + minutes; // Return total minutes from midnight
}

const filtered = [];

for (const item of $input.all()) {
  const timeString = item.json.Time;
  const timeInMinutes = parseTime(timeString);

  // 10:00 AM = 600 minutes, 12:00 PM = 720 minutes
  if (timeInMinutes !== null && timeInMinutes >= 600 && timeInMinutes < 720) {
    filtered.push({
      json: {
        ...item.json,
        nodeType: 'previousMismatch'
      },
      pairedItem: item.pairedItem
    });
  }
}

return filtered;

function convertTimeToDate(currentDate, timeString) {
  // Clean the time string - remove extra spaces
  const cleanTime = timeString.trim().replace(/\s+/g, ' ');

  // Parse the time string
  const timeMatch = cleanTime.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);

  if (!timeMatch) {
    throw new Error(`Invalid time format: ${timeString}. Expected format: "12:00PM", "12:00 PM", "01:00 AM", "01:00AM"`);
  }

  let hours = parseInt(timeMatch[1], 10);
  const minutes = parseInt(timeMatch[2], 10);
  const period = timeMatch[3].toUpperCase();

  // Validate hours and minutes
  if (hours < 1 || hours > 12) {
    throw new Error(`Invalid hours: ${hours}. Hours must be between 1 and 12`);
  }

  if (minutes < 0 || minutes > 59) {
    throw new Error(`Invalid minutes: ${minutes}. Minutes must be between 0 and 59`);
  }

  // Create a new date object based on currentDate
  const resultDate = new Date(currentDate);

  // Handle AM/PM logic
  if (period === 'PM') {
    // PM: Use currentDate with the specified time
    if (hours === 12) {
      // 12:xx PM = 12:xx (noon)
      resultDate.setUTCHours(12, minutes, 0, 0);
    } else {
      // 1:xx PM to 11:xx PM = 13:xx to 23:xx
      resultDate.setUTCHours(hours + 12, minutes, 0, 0);
    }
  } else { // AM
    // AM: Add one day to currentDate with the specified time
    resultDate.setUTCDate(resultDate.getUTCDate() + 1);

    if (hours === 12) {
      // 12:xx AM = 00:xx (midnight)
      resultDate.setUTCHours(0, minutes, 0, 0);
    } else {
      // 1:xx AM to 11:xx AM = 01:xx to 11:xx
      resultDate.setUTCHours(hours, minutes, 0, 0);
    }
  }

  return resultDate;
}

function convertMaxBet(valueString) {
  if (!valueString || typeof valueString !== 'string') {
    return 0;
  }
  // Clean the string - remove extra spaces
  const cleanString = valueString.trim();

  // Find number followed by 'k' or 'K' anywhere in the string
  // Examples: "30K", "123Kxxx", "abc 30Kxxx"
  const kMatch = cleanString.match(/(\d+(?:\.\d+)?)\s*[kK]/i);

  if (!kMatch) {
    return 0;
  }

  // Extract the numeric part
  const numericValue = parseFloat(kMatch[1]);

  // Validate the numeric value
  if (isNaN(numericValue)) {
    return 0;
  }

  // Convert to number by multiplying by 1000
  return numericValue * 1000;
}

function detectBetType(match) {
  const league = (match.League || '').toUpperCase();
  const no = (match.No || '').toString().toUpperCase();
  const maxBet = convertMaxBet(match.Maxbet);

  // 1. Check special bet types by No suffix (order matters!)
  if (no.endsWith('TB1')) return 'TB1';  // Next Booking
  if (no.endsWith('TB')) return 'TB';    // Booking
  if (no.endsWith('C1')) return 'C1';    // Next Corner
  if (no.endsWith('C')) return 'CR';     // Corner

  // 2. Check for child product format: numbers followed by letters, optionally followed by numbers
  // Examples: 12B, 13FS, 12B1, 13FS2 - This indicates OtherSport category
  const childProductPattern = /^\d+[A-Z]+\d*$/;
  if (childProductPattern.test(no)) return 'CP'; //child product

  // 3. Check by League name
  if (league.includes('FUTSAL')) return 'FS';

  // 4. Check Virtual PES games
  if (league.includes('SABA CLUB FRIENDLY') && league.includes('PES 21')) return 'PESCF';
  if (league.includes('SABA INTERNATIONAL FRIENDLY') && league.includes('PES 21')) return 'PESIF';
  if (league.includes('SABA VIETNAM V LEAGUE 1') && league.includes('PES 24')) return 'PES24';
  if (league.includes('SABA ELITE FRIENDLY') && league.includes('PES 21')) return 'PES5MIN';
  if (league.includes('PENALTY SHOOTOUTS') && league.includes('PES 23')) {
    if (league.includes('INTERNATIONAL')) return 'PKIF';
    if (league.includes('CLUB')) return 'PKCF';
  }

  // 5. Fall back to MaxBet-based classification
  if (maxBet >= 70000) return 'MJ';   // Major
  if (maxBet >= 40000 && maxBet < 70000) return 'M1';    // Minor 1
  if (maxBet >= 20000 && maxBet < 40000) return 'M2';    // Minor 2
  if (maxBet >= 8000 && maxBet < 20000) return 'M3';     // Minor 3
  if (maxBet >= 1500 && maxBet < 8000) return 'M4';      // Minor 4

  return 'Unknown';
}

function isRealGame(betType) {
  const virtualBetTypes = ['PESCF', 'PESIF', 'PES24', 'PES5MIN', 'PKIF', 'PKCF'];
  return !virtualBetTypes.includes(betType);
}

/**
 * Calculate end time for a real match
 * Rules:
 * - Both ET and PK: 3 hours
 * - Only PK: 2.5 hours
 * - Only ET: 3 hours
 * - Neither: 2 hours
 */
function calculateRealMatchEndTime(matchDate, etpkValue) {
  const endDate = new Date(matchDate);

  if (!etpkValue) {
    // No ET/PK: 2 hours
    endDate.setUTCHours(endDate.getUTCHours() + 2);
  } else if (etpkValue.includes("ET") && etpkValue.includes("PK")) {
    // Both ET and PK: 3 hours
    endDate.setUTCHours(endDate.getUTCHours() + 3);
  } else if (etpkValue.includes("PK")) {
    // Only PK: 2.5 hours (2 hours 30 minutes)
    endDate.setUTCHours(endDate.getUTCHours() + 2);
    endDate.setUTCMinutes(endDate.getUTCMinutes() + 30);
  } else if (etpkValue.includes("ET")) {
    // Only ET: 3 hours
    endDate.setUTCHours(endDate.getUTCHours() + 3);
  } else {
    // Default: 2 hours
    endDate.setUTCHours(endDate.getUTCHours() + 2);
  }

  return endDate;
}

/**
 * Calculate end time for a virtual match based on bet type
 */
function calculateVirtualMatchEndTime(matchDate, betType) {
  const endDate = new Date(matchDate);

  const durationMap = {
    'PES5MIN': 15,
    'PESCF': 20,
    'PESIF': 20,
    'PKIF': 5,
    'PKCF': 5,
    'PES24': 15
  };

  const minutesToAdd = durationMap[betType] || 15; // default 15 minutes
  endDate.setUTCMinutes(endDate.getUTCMinutes() + minutesToAdd);
  return endDate;
}

/**
 * Calculate match end date
 */
function calculateMatchEndDate(matchDate, isReal, etpkValue, betType) {
  return isReal
    ? calculateRealMatchEndTime(matchDate, etpkValue)
    : calculateVirtualMatchEndTime(matchDate, betType);
}

const allItems = $input.all();

// Find config item with nodeType
const currentDateItem = allItems.find(_ => _.json.nodeType === 'config');
// Find mismatch items with nodeType
const mismatchItems = allItems.filter(_ => _.json.nodeType === 'mismatch');
// Find previous mismatch items with nodeType
const previousMismatchItems = allItems.filter(_ => _.json.nodeType === 'previousMismatch');

const currentDate = currentDateItem.json.currentDate;
const result = [];

// Process current mismatch items
for (const item of mismatchItems) {
  const value = item.json;
  const betType = detectBetType(value);
  const etpkValue = value.ET_PK || "";
  const isETPK = !!value.ET_PK && (value.ET_PK.includes("ET") || value.ET_PK.includes("PK"));
  const isReal = isRealGame(betType);
  const matchDate = convertTimeToDate(currentDate, value.Time);
  const endDate = calculateMatchEndDate(matchDate, isReal, etpkValue, betType);

  result.push({
    json: {
      matchDate: matchDate,
      endDate: endDate,
      league: value.League,
      isETPK: isETPK,
      maxBet: convertMaxBet(value.Maxbet),
      provider: value.Provider,
      rowNumber: value.row_number,
      no: value.No,
      isEAL: !!value["Link EAL"] && value["Link EAL"].toUpperCase().includes("EAL"),
      isEXPT: !(value["Link EAL"] && value["Link EAL"].toUpperCase() === "NO EXPT"),
      betType: betType,
      isReal: isReal,
      hdpTrader: value.HDP || null,
      ouTrader: value.OU || null,
      isUnchanged: !!value.Unchanged && value.Unchanged.toLowerCase() === "x",
      isPreviousMatch: false,
      nodeType: 'mismatch'
    }
  });
}

// Process previous mismatch items
for (const item of previousMismatchItems) {
  const value = item.json;
  const matchDate = convertTimeToDate(currentDate, value.Time);
  // Subtract 1 day from matchDate
  matchDate.setUTCDate(matchDate.getUTCDate() - 1);

  const betType = detectBetType(value);
  const etpkValue = value.ET_PK || "";
  const isETPK = !!value.ET_PK && (value.ET_PK.includes("ET") || value.ET_PK.includes("PK"));
  const isReal = isRealGame(betType);
  const endDate = calculateMatchEndDate(matchDate, isReal, etpkValue, betType);

  result.push({
    json: {
      matchDate: matchDate,
      endDate: endDate,
      league: value.League,
      isETPK: isETPK,
      maxBet: convertMaxBet(value.Maxbet),
      provider: value.Provider,
      rowNumber: value.row_number,
      no: value.No,
