        ou: data.OU1,
        tier: "primary",
        league_priority: leaguePriority,
        nodeType: "pairTrader"
      }
    });
  }

  // Secondary tier: HDP + OU2 (only if OU2 exists and is not empty)
  if (data.HDP && data.OU2 && data.OU2.trim() !== '') {
    result.push({
      json: {
        hdp: data.HDP,
        ou: data.OU2,
        tier: "secondary",
        league_priority: leaguePriority,
        nodeType: "pairTrader"
      }
    });
  }

  // Backup tier: HDPBK + OUBK (only if both exist and are not empty)
